package com.medtrack.medicine.entity;
import com.medtrack.shared.model.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="medicines") public class Medicine extends BaseEntity { @Column(nullable=false,unique=true) private String sku; @Column(name="generic_name",nullable=false) private String genericName; @Column(name="brand_name") private String brandName; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="category_id",nullable=false) private MedicineCategory category; @Column(name="dosage_form",nullable=false) private String dosageForm; @Column(nullable=false) private String strength; @Column(name="unit_of_measure",nullable=false) private String unitOfMeasure; @Column(name="storage_temp") private String storageTemp; @Column(name="min_stock_threshold",nullable=false) private int minStockThreshold; @Column(name="min_receiving_shelf_life_days",nullable=false) private int minReceivingShelfLifeDays; @Enumerated(EnumType.STRING) @Column(nullable=false) private MedicineStatus status; private String description; protected Medicine(){} public Medicine(String sku,String genericName,String brandName,MedicineCategory category,String dosageForm,String strength,String unit,String temp,int minStock,int shelf,String description){this.sku=sku;this.genericName=genericName;this.brandName=brandName;this.category=category;this.dosageForm=dosageForm;this.strength=strength;this.unitOfMeasure=unit;this.storageTemp=temp;this.minStockThreshold=minStock;this.minReceivingShelfLifeDays=shelf;this.status=MedicineStatus.ACTIVE;this.description=description;} public void update(String genericName,String brandName,MedicineCategory category,String dosageForm,String strength,String unit,String temp,int minStock,int shelf,MedicineStatus status,String description){this.genericName=genericName;this.brandName=brandName;this.category=category;this.dosageForm=dosageForm;this.strength=strength;this.unitOfMeasure=unit;this.storageTemp=temp;this.minStockThreshold=minStock;this.minReceivingShelfLifeDays=shelf;this.status=status;this.description=description;} public String getSku(){return sku;} public String getGenericName(){return genericName;} public String getBrandName(){return brandName;} public MedicineCategory getCategory(){return category;} public String getDosageForm(){return dosageForm;} public String getStrength(){return strength;} public String getUnitOfMeasure(){return unitOfMeasure;} public String getStorageTemp(){return storageTemp;} public int getMinStockThreshold(){return minStockThreshold;} public int getMinReceivingShelfLifeDays(){return minReceivingShelfLifeDays;} public MedicineStatus getStatus(){return status;} public String getDescription(){return description;} }
